-- Sync the canonical skills catalog and aliases from JSON snapshots.

BEGIN;

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- Merge legacy CSS3 rows into the canonical CSS record if they exist.
DO }
DECLARE
  css_id TEXT;
  css3_id TEXT;
BEGIN
  SELECT id INTO css_id FROM "skills" WHERE LOWER("slug") = 'css' OR LOWER("canonical_name") = 'css' LIMIT 1;
  SELECT id INTO css3_id FROM "skills" WHERE LOWER("slug") = 'css3' OR LOWER("canonical_name") = 'css3' LIMIT 1;

  IF css3_id IS NOT NULL THEN
    IF css_id IS NULL THEN
      UPDATE "skills"
      SET "slug" = 'css',
          "canonical_name" = 'CSS',
          "category" = 'Frontend',
          "description" = 'Linguagem de estilo para interfaces web',
          "active" = true
      WHERE id = css3_id;
    ELSE
      UPDATE "skill_aliases" SET "skill_id" = css_id WHERE "skill_id" = css3_id;
      UPDATE "user_skills" SET "skill_id" = css_id WHERE "skill_id" = css3_id;
      UPDATE "job_skills" SET "skill_id" = css_id WHERE "skill_id" = css3_id;
      UPDATE "study_plan_items" SET "skill_id" = css_id WHERE "skill_id" = css3_id;
      DELETE FROM "skills" WHERE id = css3_id;
    END IF;
  END IF;
END };

