INSERT INTO "skills" ("id", "slug", "canonical_name", "category", "description", "active")
SELECT
  gen_random_uuid()::text,
  COALESCE(NULLIF(TRIM(catalog.slug), ''), LOWER(REGEXP_REPLACE(LOWER(catalog.canonical_name), '[^a-z0-9]+', '-', 'g'))),
  catalog.canonical_name,
  catalog.category,
  catalog.description,
  true
FROM catalog
ON CONFLICT ("slug") DO UPDATE
SET
  "canonical_name" = EXCLUDED."canonical_name",
  "category" = EXCLUDED."category",
  "description" = EXCLUDED."description",
  "active" = true;

WITH alias_seed AS (
  SELECT *
  FROM jsonb_to_recordset('[{"skill_slug":"javascript","alias":"JS"},{"skill_slug":"javascript","alias":"Java Script"},{"skill_slug":"javascript","alias":"ECMAScript"},{"skill_slug":"html","alias":"HTML5"},{"skill_slug":"css","alias":"CSS3"},{"skill_slug":"css","alias":"CSS 3"},{"skill_slug":"typescript","alias":"TS"},{"skill_slug":"typescript","alias":"Type Script"},{"skill_slug":"react","alias":"React.js"},{"skill_slug":"next-js","alias":"Next"},{"skill_slug":"node-js","alias":"Node"},{"skill_slug":"node-js","alias":"Node.js"},{"skill_slug":"express-js","alias":"Express"},{"skill_slug":"express-js","alias":"Express.js"},{"skill_slug":"csharp","alias":"C#"},{"skill_slug":"csharp","alias":"C Sharp"},{"skill_slug":"dotnet","alias":".NET"},{"skill_slug":"dotnet","alias":"Dot Net"},{"skill_slug":"postgresql","alias":"Postgres"},{"skill_slug":"postgresql","alias":"Postgre"},{"skill_slug":"mongodb","alias":"Mongo"},{"skill_slug":"machine-learning","alias":"ML"},{"skill_slug":"jwt","alias":"JSON Web Token"},{"skill_slug":"oauth","alias":"OAuth2"},{"skill_slug":"cicd","alias":"CI/CD"},{"skill_slug":"cicd","alias":"CICD"},{"skill_slug":"cicd","alias":"Continuous Integration"},{"skill_slug":"cicd","alias":"Continuous Delivery"},{"skill_slug":"rest","alias":"REST API"},{"skill_slug":"rest","alias":"API REST"},{"skill_slug":"graphql","alias":"GraphQL API"},{"skill_slug":"power-bi","alias":"PowerBI"},{"skill_slug":"power-bi","alias":"Power BI"},{"skill_slug":"websockets","alias":"WebSocket"},{"skill_slug":"swagger-openapi","alias":"OpenAPI"},{"skill_slug":"swagger-openapi","alias":"Swagger"},{"skill_slug":"tailwind-css","alias":"Tailwind"},{"skill_slug":"tailwind-css","alias":"TailwindCSS"},{"skill_slug":"frontend","alias":"Front-end"},{"skill_slug":"frontend","alias":"Front End"},{"skill_slug":"ui-ux","alias":"UI UX"},{"skill_slug":"responsividade","alias":"Responsive Design"}]'::jsonb) AS x(
    skill_slug TEXT,
    alias TEXT
  )
)
INSERT INTO "skill_aliases" ("id", "skill_id", "alias", "normalized_alias")
SELECT
  gen_random_uuid()::text,
  s."id",
  alias_seed.alias,
  REGEXP_REPLACE(LOWER(TRIM(alias_seed.alias)), '[^a-z0-9]+', '', 'g')
FROM alias_seed
JOIN "skills" s ON s."slug" = alias_seed.skill_slug
ON CONFLICT ("normalized_alias") DO UPDATE
SET
  "skill_id" = EXCLUDED."skill_id",
  "alias" = EXCLUDED."alias";

COMMIT;
